// 2026-09-21 sweep (PRIOR-31/FLOW-17): every name escaped; held drafts, info-changed notices, thank-yous and an early stop now count.
const body = $('Fetch Due').first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const initial = body.initial || [], followup = body.followup || [], dayahead = body.dayahead || [];
const updates = body.booking_updates || [];
const thankyou = (body.thankyou || []).filter((x) => x && typeof x === 'object'); // an old app returns bare ids: ignored, so deploy order doesn't matter
const held = body.held_drafts || [];
const failures = Number(body.failures) || 0;
const stoppedEarly = body.ran_out_of_time === true;
const total = initial.length + followup.length + dayahead.length + updates.length + thankyou.length + held.length;
if (!total && !stoppedEarly) return []; // failures alone: the run's own "Advance emails NOT sent" alert covers them
const TD1 = 'padding:4px 10px 4px 0;color:#6b7280;font:13px -apple-system,sans-serif', TD2 = 'padding:4px 0;font:13px -apple-system,sans-serif';
const when = (x) => { const d = x.show_date || x.event_date || ''; return d ? ' — ' + esc(d) : ''; }; // booking_updates carry event_date
const line = (x) => `<tr><td style="${TD1}">${esc(x.artist_name)}</td><td style="${TD2}">${esc(x.venue)}${when(x)}</td></tr>`;
const heldLine = (x) => { const url = /^https:\/\//i.test(x.link || '') ? x.link : ''; return `<tr><td style="${TD1}">${esc(x.artist_name)}</td><td style="${TD2}">${esc(x.venue)}${when(x)}${url ? ` — <a href="${esc(url)}">open draft</a>` : ''}</td></tr>`; };
const n = (k, one, many) => `${k} ${k === 1 ? one : many}`;
let html = '<div style="font-family:-apple-system,sans-serif">';
const sec = (label, rows, fn) => { if (!rows.length) return; html += `<p style="margin-top:14px"><b>${label}</b></p><table>${rows.map(fn || line).join('')}</table>`; };
sec(`${n(held.length,'welcome held as a draft','welcomes held as drafts')} — NOT sent`, held, heldLine);
sec(`${n(initial.length,'welcome email','welcome emails')} sent`, initial);
sec(`${n(followup.length,'follow-up','follow-ups')} sent`, followup);
sec(`${n(dayahead.length,'day-before confirmation','day-before confirmations')} sent`, dayahead);
sec(`${n(updates.length,'“booking details changed” notice','“booking details changed” notices')} sent`, updates);
sec(`${n(thankyou.length,'thank-you','thank-yous')} sent`, thankyou);
if (failures) html += `<p style="margin-top:14px"><b>${n(failures,'send','sends')} failed this run</b> — details in today’s separate “Advance emails” alert.</p>`;
if (stoppedEarly) html += '<p style="margin-top:14px"><b>Stopped early</b> to stay inside the worker time limit. Anything that didn’t go out this run goes on the next one (the next late-booking trigger, or tomorrow 9am).</p>';
html += held.length ? '<p style="margin-top:14px">The held draft(s) are waiting in Production@3cdc.org Drafts. After you send one by hand, click “Advance drafted — I sent it” on the artist page so the reminders start.</p></div>' : '<p style="margin-top:14px">Sent via Outlook — nothing to review, this is just a summary.</p></div>';
const parts = [];
if (held.length) parts.push(`${held.length} held draft${held.length===1?'':'s'}`);
if (initial.length) parts.push(`${initial.length} welcome`);
if (followup.length) parts.push(`${followup.length} follow-up`);
if (dayahead.length) parts.push(`${dayahead.length} day-before`);
if (updates.length) parts.push(`${updates.length} info-changed`);
if (thankyou.length) parts.push(`${thankyou.length} thank-you`);
if (stoppedEarly) parts.push('stopped early');
return [{ json: { subject: `Advance update — ${parts.join(', ')}`, html } }];

const EXPECTED_TOKEN = 'REPLACE_WITH_ADVANCE_INTERNAL_TOKEN';
const headers = $input.first().json.headers || {};
const token = headers['x-advance-token'];
if (token !== EXPECTED_TOKEN) {
  return [];
}
return [{ json: {} }];
